public static void backtrackingGenerico(VectorTDA<Integer> solucionParcial, int etapa, int n) throws Exception {
    // Dominio de candidatos para la etapa actual
    for (int valor = 0; valor < n; valor++) {
        solucionParcial.agregarElemento(etapa, valor);
        if (esFactible(solucionParcial, etapa)) {
            if (etapa == n - 1) {
                procesarSolucion(solucionParcial, n);
            } else {
                backtrackingGenerico(solucionParcial, etapa + 1, n);
            }
        }
        // Vuelta atrás (limpieza de estado si el TDA lo requiere)
    }
}

public static void resolverReinas(int n) throws Exception {
    VectorTDA<Integer> v = new Vector<Integer>();
    v.inicializarVector(n);
    if (reinas(n, 0, v)) {
        mostrarTablero(v, n);
    } else {
        System.out.println("No hay solución");
    }
}

private static boolean reinas(int n, int k, VectorTDA<Integer> v) throws Exception {
    boolean solucion = false;
    v.agregarElemento(k, 0);
    while (v.recuperarElemento(k) < n && !solucion) {
        if (reinasValido(k, v)) {
            if (k + 1 == n) {
                solucion = true;
            } else {
                solucion = reinas(n, k + 1, v);
            }
        }
        if (!solucion) {
            v.agregarElemento(k, v.recuperarElemento(k) + 1);
        }
    }
    return solucion;
}

private static boolean reinasValido(int k, VectorTDA<Integer> v) throws Exception {
    int colK = v.recuperarElemento(k);
    for (int i = 0; i < k; i++) {
        int colI = v.recuperarElemento(i);
        if (colI == colK || Math.abs(colI - colK) == Math.abs(i - k)) {
            return false;
        }
    }
    return true;
}

private static void mostrarTablero(VectorTDA<Integer> v, int n) throws Exception {
    for (int i = 0; i < n; i++) {
        System.out.println("Fila " + i + ": Reina en columna " + v.recuperarElemento(i));
    }
}

public static void resolverSumaSubconjunto(VectorTDA<Integer> v, int m) throws Exception {
    VectorTDA<Integer> actSol = new Vector<Integer>();
    actSol.inicializarVector(v.capacidadVector());
    subsetSum(v, m, actSol, 0, 0);
}

private static void subsetSum(VectorTDA<Integer> v, int m, VectorTDA<Integer> actSol, int actSuma, int etapa) throws Exception {
    for (int i = 0; i <= 1; i++) {
        actSol.agregarElemento(etapa, i);
        actSuma += v.recuperarElemento(etapa) * i;

        if (etapa == v.capacidadVector() - 1) {
            if (actSuma == m) {
                System.out.print("Subconjunto encontrado: { ");
                for (int j = 0; j < v.capacidadVector(); j++) {
                    if (actSol.recuperarElemento(j) == 1) {
                        System.out.print(v.recuperarElemento(j) + " ");
                    }
                }
                System.out.println("}");
            }
        } else {
            if (actSuma <= m) {
                subsetSum(v, m, actSol, actSuma, etapa + 1);
            }
        }
        actSuma -= v.recuperarElemento(etapa) * i;
    }
}

public static void resolverParticionMitades(VectorTDA<Integer> v) throws Exception {
    int n = v.capacidadVector();
    int sumaTotal = 0;
    for (int i = 0; i < n; i++) {
        sumaTotal += v.recuperarElemento(i);
    }
    if (sumaTotal % 2 != 0) {
        System.out.println("No existe partición: la suma total es impar (" + sumaTotal + ")");
        return;
    }
    VectorTDA<Integer> solucion = new Vector<Integer>();
    solucion.inicializarVector(n);
    particionRec(v, solucion, 0, 0, 0, sumaTotal / 2);
}

private static void particionRec(VectorTDA<Integer> v, VectorTDA<Integer> s, int etapa, int suma1, int suma2, int meta) throws Exception {
    int n = v.capacidadVector();
    if (etapa == n) {
        if (suma1 == suma2) {
            System.out.print("Partición hallada: S1={ ");
            for (int i = 0; i < n; i++) {
                if (s.recuperarElemento(i) == 1) System.out.print(v.recuperarElemento(i) + " ");
            }
            System.out.print("} | S2={ ");
            for (int i = 0; i < n; i++) {
                if (s.recuperarElemento(i) == 2) System.out.print(v.recuperarElemento(i) + " ");
            }
            System.out.println("}");
        }
        return;
    }

    // Probar colocar en subconjunto 1 con poda
    if (suma1 + v.recuperarElemento(etapa) <= meta) {
        s.agregarElemento(etapa, 1);
        particionRec(v, s, etapa + 1, suma1 + v.recuperarElemento(etapa), suma2, meta);
    }
    // Probar colocar en subconjunto 2 con poda
    if (suma2 + v.recuperarElemento(etapa) <= meta) {
        s.agregarElemento(etapa, 2);
        particionRec(v, s, etapa + 1, suma1, suma2 + v.recuperarElemento(etapa), meta);
    }
}

public static Integer dfsNoRecursivo(GrafoDirTDA<Integer> g, int origen, int objetivo, int totalVertices) throws Exception {
    PilaTDA<Integer> pila = new Pila<Integer>();
    pila.InicializarPila();
    ConjuntoTDA<Integer> visitados = new Conjunto<Integer>();
    visitados.inicializarConjunto();

    pila.Apilar(origen);
    visitados.agregar(origen);

    while (!pila.PilaVacia()) {
        int v = pila.Tope();
        pila.Desapilar();
        if (v == objetivo) {
            return v; // Objetivo alcanzado
        }
        ConjuntoTDA<Integer> ady = g.Adyacentes(v);
        while (!ady.conjuntoVacio()) {
            int u = ady.elegir();
            ady.sacar(u);
            if (!visitados.pertenece(u)) {
                visitados.agregar(u);
                pila.Apilar(u);
            }
        }
    }
    return null;
}

public static int busquedaCostoUniforme(GrafoDirTDA<Integer> g, int origen, int objetivo, int totalVertices) throws Exception {
    ColaPrioridadTDA<Integer> frontera = new ColaPrioridad<Integer>();
    frontera.InicializarCola();
    frontera.AgregarElemento(origen, 0.0);

    ConjuntoTDA<Integer> cerrados = new Conjunto<Integer>();
    cerrados.inicializarConjunto();

    while (!frontera.ColaVacia()) {
        double costoActual = frontera.RecuperarMinPrioridad();
        int actual = frontera.RecuperarMinElemento();
        frontera.EliminarMinPrioridad();

        if (actual == objetivo) {
            return (int) costoActual;
        }

        if (!cerrados.pertenece(actual)) {
            cerrados.agregar(actual);
            ConjuntoTDA<Integer> ady = g.Adyacentes(actual);
            while (!ady.conjuntoVacio()) {
                int vecino = ady.elegir();
                ady.sacar(vecino);
                if (!cerrados.pertenece(vecino)) {
                    double nuevoCosto = costoActual + g.PesoArista(actual, vecino);
                    frontera.AgregarElemento(vecino, nuevoCosto);
                }
            }
        }
    }
    return -1; // Inalcanzable
}

public static int aEstrella(GrafoDirTDA<Integer> g, int origen, int destino, VectorTDA<Integer> heuristica, int totalVertices) throws Exception {
    ColaPrioridadTDA<Integer> open = new ColaPrioridad<Integer>();
    open.InicializarCola();

    VectorTDA<Integer> gScore = new Vector<Integer>();
    gScore.inicializarVector(totalVertices);
    for (int i = 0; i < totalVertices; i++) gScore.agregarElemento(i, Integer.MAX_VALUE);

    gScore.agregarElemento(origen, 0);
    double fInicial = 0.0 + heuristica.recuperarElemento(origen);
    open.AgregarElemento(origen, fInicial);

    ConjuntoTDA<Integer> closed = new Conjunto<Integer>();
    closed.inicializarConjunto();

    while (!open.ColaVacia()) {
        int actual = open.RecuperarMinElemento();
        open.EliminarMinPrioridad();

        if (actual == destino) {
            return gScore.recuperarElemento(actual);
        }

        if (!closed.pertenece(actual)) {
            closed.agregar(actual);
            int gActual = gScore.recuperarElemento(actual);

            ConjuntoTDA<Integer> ady = g.Adyacentes(actual);
            while (!ady.conjuntoVacio()) {
                int vecino = ady.elegir();
                ady.sacar(vecino);
                if (!closed.pertenece(vecino)) {
                    int tentativeG = gActual + g.PesoArista(actual, vecino);
                    if (tentativeG < gScore.recuperarElemento(vecino)) {
                        gScore.agregarElemento(vecino, tentativeG);
                        double fVecino = tentativeG + heuristica.recuperarElemento(vecino);
                        open.AgregarElemento(vecino, fVecino);
                    }
                }
            }
        }
    }
    return -1;
}

public class ClasificadorJuegosNP {
    public static final int TIPO_N = 1;
    public static final int TIPO_P = -1;
    public static final int JUGADOR_MAX = 1;
    public static final int JUGADOR_MIN = -1;

    public static int evaluarNodoNP(int estado, int jugador) {
        if (esTerminal(estado)) {
            return ganaJugadorDeTurno(estado, jugador) ? TIPO_N : TIPO_P;
        }

        // Exploracion con poda: si algun hijo es P, el actual es N
        ConjuntoTDA<Integer> hijos = obtenerMovidasLegales(estado);
        hijos.inicializarConjunto();
        generarMovidas(estado, hijos);

        boolean todosHijosSonN = true;
        while (!hijos.conjuntoVacio()) {
            int sig = hijos.elegir();
            hijos.sacar(sig);

            int evalHijo = evaluarNodoNP(sig, -jugador);
            if (evalHijo == TIPO_P) {
                return TIPO_N; // Poda: movida ganadora encontrada hacia estado perdedor rival
            }
        }
        return TIPO_P; // Todos los sucesores son N, no hay escape
    }

    private static boolean esTerminal(int estado) { return estado == 0; }
    private static boolean ganaJugadorDeTurno(int estado, int j) { return true; }
    private static ConjuntoTDA<Integer> obtenerMovidasLegales(int e) { return new ConjuntoLD<>(); }
    private static void generarMovidas(int e, ConjuntoTDA<Integer> c) {
        for (int m = 1; m <= 3 && m <= e; m++) c.agregar(e - m);
    }
}

