public class AlgoritmoMinimax {
    public static final int MAX = 1;
    public static final int MIN = -1;
    public static final int INF = 1000000000;

    public static int minMax(NodoJuego e, int nivel) {
        if (e.esHoja()) {
            return e.getResultado();
        }

        int valor;
        if (nivel == MAX) {
            valor = -INF;
            for (NodoJuego sig : e.getHijos()) {
                valor = Math.max(valor, minMax(sig, MIN));
            }
        } else {
            valor = INF;
            for (NodoJuego sig : e.getHijos()) {
                valor = Math.min(valor, minMax(sig, MAX));
            }
        }
        return valor;
    }
}

public class JuegoCorchosBacktracking {
    public static final int MAX = 1;
    public static final int MIN = -1;

    public static int escabio(int e, int n) {
        // Caso base misere: si e == 0, el jugador anterior tomo el ultimo y perdio
        if (e == 0) {
            return n;
        }

        int sig = 1;
        int val = -1 * n; // Peor caso: -1 para MAX, +1 para MIN
        boolean poda = false;

        while (sig <= 3 && sig <= e && !poda) {
            e -= sig; // Efectuar movimiento
            int res = escabio(e, -n);
            e += sig; // Deshacer movimiento (Backtracking consistente)

            if (n == MAX) {
                val = Math.max(val, res);
            } else {
                val = Math.min(val, res);
            }

            // Poda: si el jugador n consiguio su utilidad maxima (1 para MAX o -1 para MIN)
            if (n * val == 1) {
                poda = true;
            }
            sig++;
        }
        return val;
    }
}

public class TaTeTiMinimax {
    public static final char VACIO = ' ';
    public static final char JUG_MAX = 'O';
    public static final char JUG_MIN = 'X';

    public static int evaluar(char[][] b, boolean esMax, int alfa, int beta) {
        if (hayTresEnLinea(b, JUG_MAX)) return 1;
        if (hayTresEnLinea(b, JUG_MIN)) return -1;
        if (estaLleno(b)) return 0;

        if (esMax) {
            int maxEval = -1000;
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (b[i][j] == VACIO) {
                        b[i][j] = JUG_MAX;
                        int eval = evaluar(b, false, alfa, beta);
                        b[i][j] = VACIO; // Backtracking
                        maxEval = Math.max(maxEval, eval);
                        alfa = Math.max(alfa, eval);
                        if (beta <= alfa) break;
                    }
                }
            }
            return maxEval;
        } else {
            int minEval = 1000;
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (b[i][j] == VACIO) {
                        b[i][j] = JUG_MIN;
                        int eval = evaluar(b, true, alfa, beta);
                        b[i][j] = VACIO; // Backtracking
                        minEval = Math.min(minEval, eval);
                        beta = Math.min(beta, eval);
                        if (beta <= alfa) break;
                    }
                }
            }
            return minEval;
        }
    }

    public static boolean hayTresEnLinea(char[][] b, char c) {
        for (int i = 0; i < 3; i++) {
            if (b[i][0] == c && b[i][1] == c && b[i][2] == c) return true;
            if (b[0][i] == c && b[1][i] == c && b[2][i] == c) return true;
        }
        if (b[0][0] == c && b[1][1] == c && b[2][2] == c) return true;
        if (b[0][2] == c && b[1][1] == c && b[2][0] == c) return true;
        return false;
    }

    public static boolean estaLleno(char[][] b) {
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++)
                if (b[i][j] == VACIO) return false;
        return true;
    }
}

public class PodaAlfaBeta {
    public static final int MAX = 1;
    public static final int MIN = -1;
    public static final int INF = 1000000000;

    public static int algoritmoAB(NodoJuego e, int n, int alfa, int beta) {
        if (e.esHoja()) {
            return e.getResultado();
        }

        int val;
        if (n == MAX) {
            val = -INF;
            for (NodoJuego sig : e.getHijos()) {
                val = Math.max(val, algoritmoAB(sig, MIN, alfa, beta));
                alfa = Math.max(alfa, val);
                if (beta <= alfa) {
                    break; // Poda Beta en nodo MAX
                }
            }
        } else {
            val = INF;
            for (NodoJuego sig : e.getHijos()) {
                val = Math.min(val, algoritmoAB(sig, MAX, alfa, beta));
                beta = Math.min(beta, val);
                if (beta <= alfa) {
                    break; // Poda Alfa en nodo MIN
                }
            }
        }
        return val;
    }
}

public class BranchAndBoundFramework {
    public static class NodoBB {
        public int id;
        public int etapa;
        public int c; // Cota inferior / costo acumulado
        public int u; // Cota superior local
        public boolean factible;

        public NodoBB(int id, int etapa, int c, int u, boolean factible) {
            this.id = id;
            this.etapa = etapa;
            this.c = c;
            this.u = u;
            this.factible = factible;
        }
    }

    public static int resolverMinimizacion(NodoBB raiz, ColaPrioridadTDA<NodoBB> env) {
        int upper = raiz.u;
        env.inicializarCola();
        env.acolar(raiz, raiz.c); // Prioridad basada en menor costo c

        NodoBB mejorSolucion = null;

        while (!env.colaVacia()) {
            NodoBB actual = env.primero();
            env.desacolar();

            // Poda por cota
            if (actual.c >= upper) {
                continue; // Killed / Podado
            }

            // En hojas terminales
            if (esHoja(actual)) {
                if (actual.c < upper) {
                    upper = actual.c;
                    mejorSolucion = actual;
                }
                continue;
            }

            // Expansion de hijos
            VectorTDA<NodoBB> hijos = generarHijos(actual);
            for (int i = 0; i < hijos.capacidadVector(); i++) {
                NodoBB h = hijos.recuperarElemento(i);
                if (h.factible) {
                    if (h.u < upper) {
                        upper = h.u; // Actualizacion de cota global
                    }
                    if (h.c < upper) {
                        env.acolar(h, h.c);
                    }
                }
            }
        }
        return upper;
    }

    private static boolean esHoja(NodoBB n) { return n.etapa >= 4; }
    private static VectorTDA<NodoBB> generarHijos(NodoBB n) { return new Vector<>(); }
}

public class SelectorEstrategiasBB {
    public enum ModoBB { FIFO, LIFO, LEAST_COST }

    public static void ejecutarTraza(ModoBB modo, int totalNodos) {
        System.out.println("Iniciando exploracion Branch & Bound en modo: " + modo);
        switch (modo) {
            case FIFO:
                // Cola FIFO: Nodos explorados estrictamente por nivel (1, 2, 3, 4, 5, 6, 7...)
                System.out.println("Consumo de memoria: O(b^d). Nodos simultaneos en nivel k: 2^(k-1)");
                break;
            case LIFO:
                // Pila LIFO: Profundizacion inmediata por rama izquierda y retroceso
                System.out.println("Consumo de memoria: O(b * d). Pila acotada por altura del arbol");
                break;
            case LEAST_COST:
                // Cola de Prioridad: Despacho por minimo costo c
                System.out.println("Expansion guiada por min(c). Podas maximizadas.");
                break;
        }
    }
}

import java.util.*;

public class JobSequencingLCBBSolver {
    public static class Trabajo {
        public int id, p, d, t;
        public Trabajo(int id, int p, int d, int t) {
            this.id = id; this.p = p; this.d = d; this.t = t;
        }
    }

    public static class Nodo {
        public int id, etapa, c, u;
        public List<Trabajo> incluidos;
        public Nodo(int id, int etapa, int c, int u, List<Trabajo> inc) {
            this.id = id; this.etapa = etapa; this.c = c; this.u = u; this.incluidos = inc;
        }
    }

    public static int resolver(Trabajo[] trabajos) {
        int totalPenalidades = 0;
        for (Trabajo t : trabajos) totalPenalidades += t.p;
        int upper = totalPenalidades;

        // Cola de prioridad ordenada por menor costo acumulado c (LC-BB)
        PriorityQueue<Nodo> env = new PriorityQueue<>(Comparator.comparingInt(a -> a.c));
        int idGen = 1;
        env.add(new Nodo(idGen++, 0, 0, totalPenalidades, new ArrayList<>()));

        Nodo mejor = null;

        while (!env.isEmpty()) {
            Nodo actual = env.poll();
            if (actual.c >= upper) continue; // Poda por cota

            if (actual.etapa == trabajos.length) {
                if (actual.c < upper) {
                    upper = actual.c;
                    mejor = actual;
                }
                continue;
            }

            Trabajo job = trabajos[actual.etapa];

            // Rama 1: Incluir job
            List<Trabajo> nuevaInc = new ArrayList<>(actual.incluidos);
            nuevaInc.add(job);
            if (esFactible(nuevaInc)) {
                int nuevoU = actual.u - job.p;
                if (nuevoU < upper) upper = nuevoU;
                if (actual.c < upper) {
                    env.add(new Nodo(idGen++, actual.etapa + 1, actual.c, nuevoU, nuevaInc));
                }
            }

            // Rama 2: Excluir job
            int nuevoC = actual.c + job.p;
            if (nuevoC < upper) {
                env.add(new Nodo(idGen++, actual.etapa + 1, nuevoC, actual.u, actual.incluidos));
            }
        }
        return upper;
    }

    public static boolean esFactible(List<Trabajo> lista) {
        // Ordenar por Early Deadline First (EDF) y verificar cumplimiento temporal
        List<Trabajo> ord = new ArrayList<>(lista);
        ord.sort(Comparator.comparingInt(a -> a.d));
        int tiempo = 0;
        for (Trabajo t : ord) {
            tiempo += t.t;
            if (tiempo > t.d) return false;
        }
        return true;
    }
}

public class MochilaBranchAndBound {
    public static class MochilaNodo {
        public int etapa, pesoParcial, actualValor, cotaInferior, cotaSuperior;
        public boolean factible;
    }

    public static int resolverMochilaBB(int[] pesos, int[] valores, int capacidad) {
        // Integracion del algoritmo de Apunte Progra III pags 100-106
        int cotaGlobal = 0;
        PriorityQueue<MochilaNodo> env = new PriorityQueue<>((a, b) -> Integer.compare(b.cotaSuperior, a.cotaSuperior));

        MochilaNodo raiz = new MochilaNodo();
        raiz.etapa = 0;
        raiz.cotaSuperior = calcularCotaFraccional(pesos, valores, capacidad, 0, 0, 0);
        env.add(raiz);

        int mejorValor = 0;
        while (!env.isEmpty()) {
            MochilaNodo n = env.poll();
            if (n.cotaSuperior <= mejorValor) continue; // Poda

            if (n.etapa == pesos.length) {
                if (n.actualValor > mejorValor) mejorValor = n.actualValor;
                continue;
            }

            // Hijo 1: Incluir objeto
            if (n.pesoParcial + pesos[n.etapa] <= capacidad) {
                MochilaNodo h1 = new MochilaNodo();
                h1.etapa = n.etapa + 1;
                h1.pesoParcial = n.pesoParcial + pesos[n.etapa];
                h1.actualValor = n.actualValor + valores[n.etapa];
                h1.cotaSuperior = calcularCotaFraccional(pesos, valores, capacidad, h1.etapa, h1.pesoParcial, h1.actualValor);
                if (h1.cotaSuperior > mejorValor) env.add(h1);
            }

            // Hijo 2: Excluir objeto
            MochilaNodo h2 = new MochilaNodo();
            h2.etapa = n.etapa + 1;
            h2.pesoParcial = n.pesoParcial;
            h2.actualValor = n.actualValor;
            h2.cotaSuperior = calcularCotaFraccional(pesos, valores, capacidad, h2.etapa, h2.pesoParcial, h2.actualValor);
            if (h2.cotaSuperior > mejorValor) env.add(h2);
        }
        return mejorValor;
    }

    private static int calcularCotaFraccional(int[] p, int[] v, int W, int etapa, int wAct, int vAct) {
        int cota = vAct;
        int rem = W - wAct;
        for (int i = etapa; i < p.length; i++) {
            if (p[i] <= rem) { rem -= p[i]; cota += v[i]; }
            else { cota += (v[i] * rem) / p[i]; break; }
        }
        return cota;
    }
}

public class AsignacionTareasBBSolver {
    public static class AsignacionNodo {
        public int etapa, costoAcumulado, cotaInferior;
        public boolean[] tareasUsadas;
    }

    public static int resolverAsignacion(int[][] M) {
        int n = M.length;
        int upper = Integer.MAX_VALUE;

        PriorityQueue<AsignacionNodo> env = new PriorityQueue<>(Comparator.comparingInt(a -> a.cotaInferior));
        AsignacionNodo raiz = new AsignacionNodo();
        raiz.etapa = 0;
        raiz.costoAcumulado = 0;
        raiz.tareasUsadas = new boolean[n];
        raiz.cotaInferior = calcularLB(M, raiz.etapa, raiz.tareasUsadas, 0);
        env.add(raiz);

        while (!env.isEmpty()) {
            AsignacionNodo actual = env.poll();
            if (actual.cotaInferior >= upper) continue; // Poda

            if (actual.etapa == n) {
                if (actual.costoAcumulado < upper) upper = actual.costoAcumulado;
                continue;
            }

            for (int j = 0; j < n; j++) {
                if (!actual.tareasUsadas[j]) {
                    AsignacionNodo hijo = new AsignacionNodo();
                    hijo.etapa = actual.etapa + 1;
                    hijo.costoAcumulado = actual.costoAcumulado + M[actual.etapa][j];
                    hijo.tareasUsadas = actual.tareasUsadas.clone();
                    hijo.tareasUsadas[j] = true;
                    hijo.cotaInferior = calcularLB(M, hijo.etapa, hijo.tareasUsadas, hijo.costoAcumulado);

                    if (hijo.cotaInferior < upper) {
                        if (hijo.etapa == n && hijo.costoAcumulado < upper) upper = hijo.costoAcumulado;
                        env.add(hijo);
                    }
                }
            }
        }
        return upper;
    }

    private static int calcularLB(int[][] M, int etapa, boolean[] usadas, int acum) {
        int lb = acum;
        for (int i = etapa; i < M.length; i++) {
            int minFila = Integer.MAX_VALUE;
            for (int j = 0; j < M.length; j++) {
                if (!usadas[j] && M[i][j] < minFila) minFila = M[i][j];
            }
            if (minFila != Integer.MAX_VALUE) lb += minFila;
        }
        return lb;
    }
}

