public class NQueensBacktracking {
    public static int countValidBoards(int boardSize) {
        int[] queenColumnsByRow = new int[boardSize];
        return exploreRow(queenColumnsByRow, 0, boardSize);
    }

    private static int exploreRow(int[] queenColumnsByRow, int currentRow, int boardSize) {
        if (currentRow == boardSize) {
            return 1;
        }
        int validSolutionsCount = 0;
        for (int candidateCol = 0; candidateCol < boardSize; candidateCol++) {
            queenColumnsByRow[currentRow] = candidateCol;
            if (isPlacementValid(queenColumnsByRow, currentRow)) {
                validSolutionsCount += exploreRow(queenColumnsByRow, currentRow + 1, boardSize);
            }
        }
        return validSolutionsCount;
    }

    private static boolean isPlacementValid(int[] queenColumnsByRow, int currentRow) {
        for (int previousRow = 0; previousRow < currentRow; previousRow++) {
            int columnDifference = Math.abs(queenColumnsByRow[currentRow] - queenColumnsByRow[previousRow]);
            int rowDifference = currentRow - previousRow;
            if (columnDifference == 0 || columnDifference == rowDifference) {
                return false;
            }
        }
        return true;
    }
}

