def count_n_queens_solutions(board_size: int) -> int:
    queen_columns = [-1] * board_size

    def is_safe(current_row: int, candidate_col: int) -> bool:
        for prev_row in range(current_row):
            col_diff = abs(candidate_col - queen_columns[prev_row])
            if col_diff == 0 or col_diff == (current_row - prev_row):
                return False
        return True

    def backtrack(row: int) -> int:
        if row == board_size:
            return 1
        total = 0
        for col in range(board_size):
            if is_safe(row, col):
                queen_columns[row] = col
                total += backtrack(row + 1)
        return total

    return backtrack(0)

