import java.util.List;

public class AlphaBetaPruning {
    public interface GameState {
        boolean isTerminal();
        int evaluateUtility();
        List<GameState> generateSuccessors();
    }

    public static int alphaBetaSearch(
        GameState state,
        int depth,
        int alpha,
        int beta,
        boolean isMaximizingPlayer
    ) {
        if (depth == 0 || state.isTerminal()) {
            return state.evaluateUtility();
        }
        if (isMaximizingPlayer) {
            int bestScore = Integer.MIN_VALUE;
            for (GameState child : state.generateSuccessors()) {
                int score = alphaBetaSearch(child, depth - 1, alpha, beta, false);
                bestScore = Math.max(bestScore, score);
                alpha = Math.max(alpha, bestScore);
                if (alpha >= beta) {
                    break;
                }
            }
            return bestScore;
        }
        int bestScore = Integer.MAX_VALUE;
        for (GameState child : state.generateSuccessors()) {
            int score = alphaBetaSearch(child, depth - 1, alpha, beta, true);
            bestScore = Math.min(bestScore, score);
            beta = Math.min(beta, bestScore);
            if (alpha >= beta) {
                break;
            }
        }
        return bestScore;
    }
}

