from typing import Protocol

class GameNode(Protocol):
    def is_terminal(self) -> bool: ...
    def utility(self) -> int: ...
    def children(self) -> list['GameNode']: ...

def alpha_beta_search(node: GameNode, depth: int, alpha: float, beta: float, maximizing: bool) -> float:
    if depth == 0 or node.is_terminal():
        return float(node.utility())
    if maximizing:
        best_value = float('-inf')
        for child in node.children():
            best_value = max(best_value, alpha_beta_search(child, depth - 1, alpha, beta, False))
            alpha = max(alpha, best_value)
            if alpha >= beta:
                break
        return best_value
    best_value = float('inf')
    for child in node.children():
        best_value = min(best_value, alpha_beta_search(child, depth - 1, alpha, beta, True))
        beta = min(beta, best_value)
        if alpha >= beta:
            break
    return best_value
